    if (!namaKunci_(nm) && !ni) continue;
    h.push({ nama: nm, nim: /^3030\d{7}$/.test(ni) ? ni : '', ket: kK >= 0 ? teks_(isi[b][kK]) : '' });
  }
  return h;
}
